"""Tasks, SLAs, Reminders, and In-App Notifications models.

Source Authority: Cadence_TPRM_Training.docx Section 4.2, 5.1, Appendix D, Table 13.
"""

import uuid
from datetime import datetime, timezone
from sqlalchemy import Column, String, Boolean, DateTime, ForeignKey, Text
from sqlalchemy.orm import relationship
from src.cadence_tprm.database import Base

def generate_uuid():
    return str(uuid.uuid4())

class Task(Base):
    """Authoritative tasks generated by Table 10, Table 13, and Table 14:

    - Assessment Submitted (Approvers & All TPRM Groups)
    - Low Assessment Score (VRM Group)
    - Review Reject Followup (14-day SLA to Business Owner)
    - High/Medium/Low Risk Response tasks
    - Departmental Review Tasks (Legal, Finance, Procurement, Security, IT, Privacy, Compliance, Data Quality)
    """
    __tablename__ = "tasks"

    id = Column(String(36), primary_key=True, default=generate_uuid)
    vendor_id = Column(String(36), ForeignKey("vendors.id", ondelete="CASCADE"), nullable=False, index=True)
    assessment_id = Column(String(36), ForeignKey("assessments.id", ondelete="CASCADE"), nullable=True)
    task_type = Column(String(100), nullable=False)
    title = Column(String(255), nullable=False)
    description = Column(Text, nullable=True)
    
    assignee_email = Column(String(255), nullable=True, index=True)
    collaborator_group = Column(String(100), nullable=True, index=True)
    
    # SLA & Reminders
    due_date = Column(DateTime, nullable=False, index=True)
    reminder_date = Column(DateTime, nullable=True)
    reminder_sent = Column(Boolean, default=False, nullable=False)
    
    # Status: Pending, In Progress, Completed, Overdue
    status = Column(String(50), nullable=False, default="Pending", index=True)
    completed_at = Column(DateTime, nullable=True)
    created_at = Column(DateTime, default=lambda: datetime.now(timezone.utc), nullable=False)

    vendor = relationship("Vendor", back_populates="tasks")

class Notification(Base):
    __tablename__ = "notifications"

    id = Column(String(36), primary_key=True, default=generate_uuid)
    recipient_email = Column(String(255), nullable=False, index=True)
    subject = Column(String(255), nullable=False)
    body = Column(Text, nullable=False)
    notification_type = Column(String(50), nullable=False, default="InApp")  # InApp, Email
    is_read = Column(Boolean, default=False, nullable=False, index=True)
    link_url = Column(String(255), nullable=True)
    created_at = Column(DateTime, default=lambda: datetime.now(timezone.utc), nullable=False)
